"},{"node":"TestCancellationDuringExecution","qualified_name":"bench-repo.internal.scheduler.TestCancellationDuringExecution","label":"Function","file":"internal/scheduler/integration_test.go","start_line":126,"end_line":178,"in_degree":0,"out_degree":5,"match_lines":[132],"source":"func TestCancellationDuringExecution(t *testing.T) {
	var canceled atomic.Bool
	var started atomic.Bool

	s := scheduler.New()

	s.Register(&scheduler.Job{
		Name:     "long-job",
		Schedule: "* * * * * *",
		Handler: func(ctx context.Context) error {
			started.Store(true)
			// Simulate long-running work
			for i := 0; i < 100; i++ {
				select {
				case <-ctx.Done():
					canceled.Store(true)
					return ctx.Err()
				case <-time.After(100 * time.Millisecond):
					// Keep working
				}
			}
			return nil
		},
	})

	if err := s.Start(); err != nil {
		t.Fatalf("failed to start: %v", err)
	}

	// Wait until job starts
	for i := 0; i < 30; i++ {
		if started.Load() {
			break
		}
		time.Sleep(100 * time.Millisecond)
	}

	if !started.Load() {
		t.Fatal("job did not start within timeout")
	}

	// Stop with reasonable timeout
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	if err := s.Stop(ctx); err != nil {
		t.Logf("stop returned error (may be expected): %v", err)
	}

	if !canceled.Load() {
		t.Error("expected job to detect cancellation")
	}
}
